// =====================================================================
//  RULES BRAIN (no AI)  -  edit the RULE PACKS and TEMPLATES below.
//  You do not need to know JavaScript. Just follow the patterns:
//    - text goes inside "double quotes"
//    - every line inside a { ... } block ends with a comma
//    - numbers have no quotes (20, not "20")
//  After editing, click "Execute step" to check there are no red errors.
// =====================================================================

// ---------------------------------------------------------------------
//  RULE PACKS
//  A rule pack is a list of checks. The caller picks one by name,
//  e.g. ruleset: "lead_scoring".
//
//  Each rule looks like:
//    { fact: "budget", check: "atLeast", value: 5000, points: 25,
//      reason: "Budget is 5,000 or more" },
//
//    fact    = the name of the field to look at inside "facts"
//    check   = what to test. One of:
//                "isPresent"     - field is filled in
//                "isMissing"     - field is empty or absent
//                "equals"        - field equals value exactly (ignores case)
//                "isOneOf"       - field equals any item in a list
//                "containsAny"   - field contains any word/phrase in a list
//                "containsNone"  - field contains none of the list
//                "atLeast"       - number is >= value
//                "atMost"        - number is <= value
//                "between"       - number is within [low, high]
//    value   = what to compare against (a number, text, or [a list])
//    points  = added to the score when the check passes
//              (use a minus number, e.g. -15, to take points away)
//    reason  = plain-English sentence shown when the check passes
//
//  startScore = points every item starts with (usually 0)
//  tiers      = score bands, checked top to bottom; first match wins
//  mustHave (optional) = facts you need before you can judge at all.
//               If any are missing, the tier becomes the "needsInfoTier"
//               name instead of a score band, so a lead is never written
//               off just because we do not know something yet.
//  template   = which TEMPLATE (below) to use for the draft
//  templateByTier (optional) = a different template per tier
// ---------------------------------------------------------------------
const RULE_PACKS = {

  lead_scoring: {
    description: "Scores an inbound lead for fit and urgency.",
    startScore: 0,
    rules: [
      // --- Fit: company size ---
      { fact: "company_size", check: "atLeast", value: 200, points: 20, reason: "Company has 200+ employees" },
      { fact: "company_size", check: "between", value: [20, 199], points: 12, reason: "Company has 20-199 employees" },
      { fact: "company_size", check: "atMost", value: 19, points: 4, reason: "Small company (under 20 employees)" },

      // --- Fit: budget (monthly, in your currency) ---
      { fact: "budget", check: "atLeast", value: 5000, points: 25, reason: "Budget is 5,000 or more" },
      { fact: "budget", check: "between", value: [1500, 4999], points: 12, reason: "Budget is 1,500-4,999" },
      { fact: "budget", check: "atMost", value: 1499, points: -10, reason: "Budget is below 1,500 (below our minimum)" },

      // --- Authority: job title ---
      { fact: "role", check: "containsAny", value: ["founder", "ceo", "owner", "cmo", "vp", "head of", "director"], points: 20, reason: "Contact is a decision-maker" },
      { fact: "role", check: "containsAny", value: ["manager", "lead"], points: 8, reason: "Contact is a manager (may need sign-off)" },
      { fact: "role", check: "containsAny", value: ["intern", "student"], points: -10, reason: "Contact is unlikely to be a buyer" },

      // --- Urgency: timeline ---
      { fact: "timeline", check: "containsAny", value: ["asap", "right now", "this month", "this week", "immediately", "urgent"], points: 15, reason: "Wants to start within a month" },
      { fact: "timeline", check: "containsAny", value: ["next month", "this quarter", "1-3 months"], points: 8, reason: "Wants to start within a quarter" },

      // --- Source quality ---
      { fact: "source", check: "isOneOf", value: ["referral", "demo request", "partner"], points: 10, reason: "Came from a high-intent source" },

      // --- Email quality ---
      { fact: "email", check: "containsAny", value: ["@gmail.", "@yahoo.", "@hotmail.", "@outlook.", "@icloud."], points: -5, reason: "Uses a personal email address, not a work one" },

      // --- Did they tell us what they need? ---
      { fact: "message", check: "isPresent", points: 5, reason: "Left a message describing their need" },
      { fact: "message", check: "isOneOf", value: ["test", "testing", "asdf", "hi", "hello"], points: -20, reason: "Message looks like a test or junk" },
    ],
    tiers: [
      { min: 70, name: "Hot" },
      { min: 40, name: "Warm" },
      { min: 0,  name: "Cold" },
    ],
    mustHave: ["budget"],
    needsInfoTier: "Needs info",
    templateByTier: {
      "Hot": "lead_reply_hot",
      "Warm": "lead_reply_warm",
      "Cold": "lead_reply_cold",
      "Needs info": "lead_reply_warm",
    },
  },

  client_health: {
    description: "Flags retainer clients who may be at risk of leaving.",
    startScore: 50,
    rules: [
      { fact: "days_since_last_reply", check: "atLeast", value: 14, points: -25, reason: "Client has not replied in 14+ days" },
      { fact: "days_since_last_reply", check: "atMost", value: 3, points: 10, reason: "Client replied in the last 3 days" },
      { fact: "overdue_invoices", check: "atLeast", value: 1, points: -20, reason: "Client has an overdue invoice" },
      { fact: "deliverables_late", check: "atLeast", value: 2, points: -15, reason: "We are late on 2+ deliverables" },
      { fact: "nps", check: "atLeast", value: 9, points: 20, reason: "Client gave a 9-10 satisfaction score" },
      { fact: "nps", check: "atMost", value: 6, points: -20, reason: "Client gave a 0-6 satisfaction score" },
      { fact: "months_retained", check: "atLeast", value: 12, points: 10, reason: "Client has stayed 12+ months" },
    ],
    tiers: [
      { min: 70, name: "Healthy" },
      { min: 40, name: "Watch" },
      { min: 0,  name: "At risk" },
    ],
    template: "client_checkin",
  },

};

// ---------------------------------------------------------------------
//  TEMPLATES
//  Write the draft text. Put a fact name inside double curly braces,
//  e.g. {{name}}, and it is replaced with that fact.
//  If a fact is missing, the draft shows DATA NEEDED instead - it never
//  guesses. You can also use {{score}}, {{tier}} and {{task}}.
//  Use \n for a new line.
// ---------------------------------------------------------------------
const TEMPLATES = {

  lead_reply_hot:
    "Subject: Next steps for {{company}}\n\n" +
    "Hi {{name}},\n\n" +
    "Thanks for reaching out about {{message}}. Based on your timeline ({{timeline}}) " +
    "and budget ({{budget}}), we look like a strong fit.\n\n" +
    "Could we book a 30-minute call this week? Here is my calendar: {{booking_link}}\n\n" +
    "Best,\n{{sender_name}}",

  lead_reply_warm:
    "Subject: Re: your enquiry\n\n" +
    "Hi {{name}},\n\n" +
    "Thanks for getting in touch about {{message}}. To see if we are the right fit for " +
    "{{company}}, could you share your rough monthly budget and when you would like to start?\n\n" +
    "Best,\n{{sender_name}}",

  lead_reply_cold:
    "Subject: Thanks for reaching out\n\n" +
    "Hi {{name}},\n\n" +
    "Thanks for your message. We may not be the best fit right now, but here are some " +
    "free resources that might help: {{resources_link}}\n\n" +
    "Best,\n{{sender_name}}",

  client_checkin:
    "Subject: Quick check-in\n\n" +
    "Hi {{name}},\n\n" +
    "Just checking in on {{project}}. Status: {{tier}} ({{score}}/100).\n\n" +
    "Best,\n{{sender_name}}",

};

// Text used for any fact the Brain does not have.
const MISSING = "DATA NEEDED";

// =====================================================================
//  ENGINE - you should not need to edit anything below this line.
// =====================================================================

function isEmpty(v) {
  if (v === undefined || v === null) return true;
  if (typeof v === "string") return v.trim() === "";
  if (Array.isArray(v)) return v.length === 0;
  return false;
}

// "5,000" -> 5000, "$1.5k" -> 1500, "11-50" -> 30.5 (middle of a range).
function toNumber(v) {
  if (typeof v === "number") return Number.isFinite(v) ? v : null;
  if (typeof v !== "string") return null;
  const found = [...v.replace(/,/g, "").matchAll(/(\d+(?:\.\d+)?)\s*([km])?\b/gi)].map((m) => {
    let n = parseFloat(m[1]);
    if (m[2]) n *= m[2].toLowerCase() === "k" ? 1000 : 1000000;
    return n;
  });
  if (found.length === 0) return null;
  if (found.length >= 2 && /\d\s*[km]?\s*(-|to)\s*\$?\d/i.test(v)) return (found[0] + found[1]) / 2;
  return found[0];
}

function toText(v) {
  if (Array.isArray(v)) return v.map(toText).join(", ");
  if (v && typeof v === "object") return JSON.stringify(v);
  return String(v);
}

function asList(value) {
  return (Array.isArray(value) ? value : [value]).map((x) => String(x).toLowerCase());
}

// Returns true / false, or null when the fact cannot be checked.
function runCheck(rule, raw) {
  if (rule.check === "isMissing") return isEmpty(raw);
  if (rule.check === "isPresent") return !isEmpty(raw);
  if (isEmpty(raw)) return null;

  const text = toText(raw).toLowerCase().trim();
  const list = asList(rule.value);
  switch (rule.check) {
    case "equals":       return text === list[0];
    case "isOneOf":      return list.includes(text);
    case "containsAny":  return list.some((w) => text.includes(w));
    case "containsNone": return !list.some((w) => text.includes(w));
    case "atLeast":
    case "atMost":
    case "between": {
      const n = toNumber(raw);
      if (n === null) return null;
      if (rule.check === "atLeast") return n >= Number(rule.value);
      if (rule.check === "atMost") return n <= Number(rule.value);
      return n >= Number(rule.value[0]) && n <= Number(rule.value[1]);
    }
    default:
      throw new Error('Unknown check "' + rule.check + '" on fact "' + rule.fact + '"');
  }
}

function fillTemplate(template, values) {
  return template.replace(/\{\{\s*([\w.]+)\s*\}\}/g, (_, key) =>
    isEmpty(values[key]) ? MISSING : toText(values[key])
  );
}

function think(input) {
  let facts = input.facts;
  if (typeof facts === "string") {
    try { facts = JSON.parse(facts); } catch (e) { facts = {}; }
  }
  if (!facts || typeof facts !== "object") facts = {};

  const packName = String(input.ruleset || "").trim();
  const pack = RULE_PACKS[packName];
  if (!pack) {
    return {
      ...input,
      scored: false,
      score: 0,
      tier: "UNSCORED",
      reasons: ['No rule pack called "' + packName + '". Available: ' + Object.keys(RULE_PACKS).join(", ")],
      draft: "",
    };
  }

  let score = Number(pack.startScore) || 0;
  const reasons = [];
  if (score) reasons.push("Starting score: " + score);
  const unchecked = new Set();

  for (const rule of pack.rules) {
    const raw = facts[rule.fact];
    const result = runCheck(rule, raw);
    if (result === null) { unchecked.add(rule.fact); continue; }
    if (result) {
      score += rule.points;
      const sign = rule.points >= 0 ? "+" : "";
      const shown = isEmpty(raw) ? "" : " (" + rule.fact + ": " + toText(raw) + ")";
      reasons.push(sign + rule.points + ": " + rule.reason + shown);
    }
  }
  for (const f of unchecked) {
    reasons.push("0: Could not check \"" + f + "\" - " + MISSING);
  }
  if (reasons.length === 0) reasons.push("No rules matched.");

  score = Math.max(0, Math.min(100, Math.round(score)));
  let tier = (pack.tiers.find((t) => score >= t.min) || { name: "Unrated" }).name;
  const missingMust = (pack.mustHave || []).filter((f) => isEmpty(facts[f]));
  if (missingMust.length > 0) {
    tier = pack.needsInfoTier || "Needs info";
    reasons.push("Tier set to \"" + tier + "\" because these must-have facts are missing: " + missingMust.join(", "));
  }

  const templateName =
    input.template || (pack.templateByTier && pack.templateByTier[tier]) || pack.template;
  const template = TEMPLATES[templateName];
  const draft = template
    ? fillTemplate(template, { ...facts, score, tier, task: input.task })
    : MISSING + ': no template called "' + templateName + '"';

  return { ...input, scored: true, score, tier, reasons, draft };
}

return $input.all().map((item, i) => ({ json: think(item.json), pairedItem: i }));
